with flagged as (select *, case when lag(started_at) over (partition by customer_id order by started_at, id) is null or started_at > lag(started_at) over (partition by customer_id order by started_at, id) + interval 14 days then 1 else 0 end as session_start_flag from sessions), sessionized as (select id, customer_id, started_at, sum(session_start_flag) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as session_id from flagged) select date_trunc('week', started_at) as week_start, date_trunc('month', started_at) as activity_month, percentile_approx(session_id, 0.95) as session_id_p95, round(avg(session_id), 2) as avg_session_id, sum(session_id) as total_session_id from sessionized group by cube (date_trunc('week', started_at), date_trunc('month', started_at)) order by total_session_id nulls first;
